INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13723,'frFR','Vous vous êtes montré digne du titre de champion, $N. Vous allez participer au plus haut niveau du tournoi au nom de Gnomeregan, chevauchant dans la grande mêlée, l\'arme au poing et arborant nos couleurs.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13724,'frFR','Vous vous êtes montré digne du titre de champion, $N. Vous allez participer au plus haut niveau du tournoi au nom de l\'Exodar, chevauchant dans la grande mêlée, l\'arme au poing et arborant nos couleurs.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13725,'frFR','Vous vous êtes montré digne du titre de champion, $N. Vous allez participer au plus haut niveau du tournoi au nom de Darnassus, chevauchant dans la grande mêlée, l\'arme au poing et arborant nos couleurs.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13726,'frFR','Vous vous êtes montré digne du titre de champion, $N. Vous allez participer au plus haut niveau du tournoi, chevauchant dans la grande mêlée et écrasant vos adversaires sous la bannière d\'Orgrimmar.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13727,'frFR','Vous vous êtes montré digne du titre de champion, $N. Vous allez participer au plus haut niveau du tournoi, chevauchant dans la grande mêlée et écrasant vos adversaires sous la bannière des Sombrelances.',0);
