INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13739,'frFR','Je vous souhaite la bienvenue comme champion du tournoi, $N. Vous pouvez désormais participer au grand championnat du tournoi. Vous pouvez aussi choisir de devenir un vaillant pour la délégation d\'une autre ville de la Horde et avec le temps, également un champion de cette ville.$b$bTous les champions doivent être aidés d\'un écuyer, $N, et vous ne faites pas exception. Permettez-moi de vous assigner l\'un des nôtres pour vous accompagner au combat. Il portera fièrement la bannière de l\'une des villes qui vous a nommé champion.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13740,'frFR','Je vous souhaite la bienvenue comme champion du tournoi, $N. Vous pouvez désormais participer au grand championnat du tournoi. Vous pouvez aussi choisir de devenir un vaillant pour la délégation d\'une autre ville de la Horde et avec le temps, également un champion de cette ville.$b$bTous les champions doivent être aidés d\'un écuyer, $N, et vous ne faites pas exception. Permettez-moi de vous assigner l\'un des nôtres pour vous accompagner au combat. Il portera fièrement la bannière de l\'une des villes qui vous a nommé champion.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13741,'frFR','Alors la légende disait vrai ? C\'est une belle lame que voilà, et je ne doute pas qu\'elle me servira bien durant le tournoi. Vous avez tous mes remerciements, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13742,'frFR','<Le grand champion accepte la lame de Drak\'Mar que vous lui tendez.>$b$bUne arme remarquable, et parfaitement équilibrée. Elle me sera très utile pour le prochain défi.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13743,'frFR','La lame est aussi remarquable que le disait la légende. Je ne vois pas l\'intérêt de réparer ma lame habituelle. Le Fil de l\'hiver lui est bien supérieure, je vais garder celle-ci. Je vous remercie, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13744,'frFR','Vous voilà de retour de vos exercices, $N. Même lorsque nous nous entraînons pour la compétition, il est bon de se rappeler que le Fléau est encore là, dehors.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13745,'frFR','Bien joué. S\'entraîner contre les autres vaillants est l\'une des meilleures manières de se préparer au tournoi. Je sais que Forgefer sera fier de vous, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13746,'frFR','Alors la légende disait vrai ? C\'est une belle lame que voilà, et je ne doute pas qu\'elle me servira bien durant le tournoi. Vous avez tous mes remerciements, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13747,'frFR','<Ambrose accepte la lame de Drak\'Mar que vous lui tendez.>$b$bUne arme remarquable, et parfaitement équilibrée. Elle me sera très utile pour le prochain défi.',0);
