INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13759,'frFR','La lame est aussi remarquable que le disait la légende. Je ne vois pas l\'intérêt de réparer ma lame habituelle. Le Fil de l\'hiver lui est bien supérieure, je vais garder celle-ci. Je vous remercie, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13760,'frFR','Vous voilà de retour de vos exercises, $N. Même lorsque nous nous entraînons pour la compétition, il est bon de se rappeler que le Fléau est encore là, dehors.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13761,'frFR','Bien joué. S\'entraîner contre les autres vaillants est l\'une des meilleures manières de se préparer au tournoi. Je sais que Darnassus sera fière de vous, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13762,'frFR','Alors la légende disait vrai ? Cette lame devrait me permettre de battre n\'importe quel adversaire de l\'Alliance.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13763,'frFR','C\'est une excellente arme qui m\'aidera à écraser mes concurrents. Merci, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13764,'frFR','La lame est aussi remarquable que le disait la légende. Je ne vois pas l\'intérêt de réparer ma lame habituelle. Le Fil de l\'hiver lui est bien supérieure, je vais garder celle-ci. Je vous remercie, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13765,'frFR','Une bonne journée d\'entraînement ne fait de mal à personne. C\'est bon de voir que vous persévérez.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13767,'frFR','En vous entraînant contre les autres vaillants, vous vous ferez les griffes et améliorerez vos instincts au combat. Quand la compétition commencera, vous serez prêt.',0);
