INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13772,'frFR','Vous entraîner contre d\'autres vaillants vous apprendra rapidement tout ce dont vous avez besoin pour les battre. Continuez comme ça et vous n\'aurez aucun problème pour les vaincre pendant la compétition.',0);
