INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13779,'frFR','C\'est une excellente arme qui m\'aidera à écraser mes concurrents. Merci, $N.',0);
INSERT IGNORE INTO `quest_offer_reward_locale` VALUES (13780,'frFR','La lame est aussi remarquable que le disait la légende. Je ne vois pas l\'intérêt de réparer ma lame habituelle. Le Fil de l\'hiver lui est bien supérieure, je vais garder celle-ci. Je vous remercie, $N.',0);
