INSERT IGNORE INTO `quest_request_items_locale` VALUES (8842,'frFR','Les aventuriers qui n\'ont qu\'une seule chevalière de mérite ne recevront qu\'une reconnaissance minime de la part des Pitons du Tonnerre.$b$bN\'oubliez pas qu\'il est préférable de remettre une série de dix chevalières à la fois. Si vous procédez ainsi, vos efforts seront mieux reconnus. Nous proposons cet échange comme un service pour ceux qui n\'ont pas une pile de dix.$b$bCeci posé, je suis en mesute de vous aider si vous souhaitez me remettre une seule chevalière.',0);
