INSERT IGNORE INTO `quest_request_items_locale` VALUES (11128,'frFR','Avez-vous réussi à trouver et à prendre les pamphlets de propagande restants ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11132,'frFR','Humm, $N, c’est bien ça ?$B$BAvez-vous déjà retrouvé ma carte ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11133,'frFR','J\'ai cru entendre des rires en provenance de la caserne. Avez-vous distribué les pamphlets ?',0);
