INSERT IGNORE INTO `quest_request_items_locale` VALUES (11155,'frFR','Rien ne surpasse la viande tendre prélevée sur les flancs des brochepelles !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11159,'frFR','Brogg veut savoir, vous avez donné la paix pour les esprits des Cognepierres ?',0);
