INSERT IGNORE INTO `quest_request_items_locale` VALUES (11164,'frFR','Grouille-toi !$B$BBudd va m\'envoyer tout seul à Zul\'Aman pour tester son masque si j\'lui file pas les défenses bientôt !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11167,'frFR','Vous êtes-vous procuré les conteneurs, $N ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11168,'frFR','Avez-vous les glandes à toxines dont j\'ai besoin, $N ?',0);
