INSERT IGNORE INTO `quest_request_items_locale` VALUES (11173,'frFR','Vous avez le venin ? Morlann peut se rendre compte de son absence à n\'importe quel moment maintenant...',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11174,'frFR','Êtes-vous parvenu à quelque chose contre ces limons ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11178,'frFR','<Budd essaye de cacher son mécontentement à vous voir.>$b$bEncore vous...$b$bJe ne vois pas comment vous le dire autrement : je suis vraiment trop occupé avec mes préparatifs pour continuer à vous tenir la main.$b$bCroyez-moi, $N, ça vaut mieux comme ça. Peut-être que, par miracle, vous arriverez un jour à vous faire un nom.$b$bSi ça arrive un jour, vous pourrez dire que c’est l’incomparable Budd Truducou qui vous a mis le pied à l’étrier !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11181,'frFR','Vous avez pu cueillir certaines de ces plantes ? Nous devons nous mettre au travail rapidement, avant que le mal caché derrière cette infection ne consolide son emprise sur la région.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11183,'frFR','C\'est terminé ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11185,'frFR','Que m\'apportez-vous, prêtresse ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11190,'frFR','On est salement près de manquer de munitions, $c. Nos ennemis ont bien b’soin qu’on leur en r’mette une dose, surtout Mörg !$b$bVous avez des boulets pour nous ?',0);
