INSERT IGNORE INTO `quest_request_items_locale` VALUES (11207,'frFR','<Moxie semble trembler d\'inquiétude.>$B$BAlors, la cargaison est encore intacte ? Vous en avez retrouvé ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11209,'frFR','N\'oubliez pas que la consigne, c\'est « ne revenez pas tant que vous ne vous êtes pas fait mordre ».',0);
