INSERT IGNORE INTO `quest_request_items_locale` VALUES (11218,'frFR','Les travaux de construction ne s’arrêtent jamais. J’espère que vous pourrez récupérer ce dont nous avons besoin pour continuer.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11237,'frFR','Hein ?! Un plan d’attaque du donjon ?$b$bAVEC UN WYRM DE GIVRE ?!!!',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11238,'frFR','L’attaque a-t-elle été stoppée ? Le wyrm de givre et son maître ont-ils été détruits ?$b$bVous avez récupéré le cor ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11249,'frFR','Oui ? Comment puis-je vous aider, mon enfant ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11254,'frFR','Vous avez quelque chose à me montrer, druide ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11260,'frFR','Oui ? Comment puis-je vous aider, mon enfant ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11261,'frFR','Quelles sont les nouvelles de Mörg, $N ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11266,'frFR','Hein ?! Un plan d’attaque de notre camp ?$b$bPAR UN GRAND WYRM DANS LE CIEL ?!!',0);
