INSERT IGNORE INTO `quest_request_items_locale` VALUES (11327,'frFR','Cet endroit est un vrai cauchemar. Vrykuls ou pas vrykuls, personne ne mérite d’être victime de la Société royale des apothicaires.$b$bHeureusement, moi, je suis tranquillement à l’abri ici. Vous avez trouvé ce paquet ?',0);
