INSERT IGNORE INTO `quest_request_items_locale` VALUES (11354,'frFR','La cravache, s\'il-vous-plaît.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11362,'frFR','Vous revenez me voir… C’est que vous devez avoir le bâton.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11363,'frFR','On murmure que le chef de guerre a des armes à la place de ses mains. C’est vrai ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11368,'frFR','Je suppose que vous connaissez un moyen pour conserver le cœur durant la livraison ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11369,'frFR','Vous revenez me voir parce que vous avez l’œuf ? Extraordinaire, montrez-le moi !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11370,'frFR','Mon client s’impatiente. Je crois qu’il souhaite étudier en profondeur les pensées tactiques du seigneur de guerre pour l’aider dans l’un de ses conflits.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11372,'frFR','L\'heure de la cérémonie du chef approche.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11377,'frFR','Est-ce que je sens l\'arôme d\'un mets délicieux ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11378,'frFR','La tête du chasseur d’époque... Comment peut-on arriver à la décision de la mettre sur un mur ?$B$BEt quand bien même, le faire sans avoir chassé soi-même la créature, que dire ensuite aux amis qui demanderont le récit du combat ?$B$BJe suppose qu’il se contentera de mentir.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11379,'frFR','Comment marche ma petite expérience ?',0);
