INSERT IGNORE INTO `quest_request_items_locale` VALUES (11381,'frFR','Qu\'est-ce qui sent si bon ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11384,'frFR','Vous vous êtes perdu en allant à la Botanica ? Vous ne pouvez pas la rater... C’est au donjon de la Tempête, derrière le bord est du Raz-de-Néant.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11386,'frFR','Ce n’est pas que la technologie du projecteur soit quelque chose de particulièrement innovant, mais la portée de ce modèle est vraiment une percée !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11388,'frFR','Ce doit être particulièrement dangereux de se mêler des affaires des Dieux très anciens.$B$BJe vous laisse vous en charger !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11395,'frFR','Quel étrange appareil vous avez là, $c. Laissez-moi le regarder de plus près.',0);
