INSERT IGNORE INTO `quest_request_items_locale` VALUES (11470,'frFR','Vous avez la main, $N. Guidez votre épervier et rapportez-moi ces œufs.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (11471,'frFR','Alors, $N. Avez-vous la longue-vue de Jonas ?$b$bParce que sans elle, vous aurez beau me jurer que vous l\'avez tué, ça ne me suffira pas, vous comprenez ? Je suis une pirate, quand même.',0);
