INSERT IGNORE INTO `quest_request_items_locale` VALUES (12877,'frFR','Bonjour, $r.$b$bJe suis ravi que vous ayez opté pour la parole plutôt que pour la lame pour faire ma connaissance. C\'est une qualité qui se fait de plus en plus rare parmi vos semblables.',0);
