INSERT IGNORE INTO `quest_request_items_locale` VALUES (12891,'frFR','Quand vous aurez réussi à obtenir ce que je vous ai demandé, je créerai l\'objet, avec quelques modifications pour nous aider dans notre but, et on pourra y aller.',0);
