INSERT IGNORE INTO `quest_request_items_locale` VALUES (13055,'frFR','Hé mec, déjà là ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13058,'frFR','Vous l\'avez fait ? La ligne de temps est restaurée ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13059,'frFR','Je sens que vous n\'avez pas encore vaincu le thane Illskar. Y a-t-il quelque chose qui retient votre bras ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13074,'frFR','C\'est bon de vous voir sain et sauf. Avez-vous récupéré les glands ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13075,'frFR','Salutations, $c. Je savais que vous reviendriez en dépit de mes avertissements, mais je suis heureux de voir que vous avez respecté mon désir de n\'impliquer personne d\'autre.$b$bPourquoi êtes-vous revenu me voir ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13078,'frFR','Ah, chère Dahlia. Vous me manquez tellement.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13079,'frFR','Vous revoilà à nouveau, $c. Pourquoi risquer ainsi votre vie ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13083,'frFR','Il est mort, n\'est-ce pas ? J\'ai senti un petit morceau de Lumière quitter cette terre.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13087,'frFR','OÙ EST MA VIANDE ?!',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13088,'frFR','Les hommes ont besoin de viande pour leur ragoût.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13089,'frFR','Le ragoût attend…',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13090,'frFR','Quand vous amènerez la viande, je pourrai préparer le ragoût.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13091,'frFR','Ma lecture des ossements me dit que vous n\'avez pas encore tout à fait fini.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13092,'frFR','Je trouve remarquable que ces êtres aient pu dominer le monde alors qu\'ils utilisent une magie si primitive.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13093,'frFR','Rapportez-moi plus d\'os de vrykuls et nous pourrons influencer le destin en votre faveur.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13095,'frFR','S\'il vous plaît, $N, dites-moi que vous avez trouvé les documents de Berinand...',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13098,'frFR','Les tablettes, vous les avez trouvées, mec ?',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13100,'frFR','Est-ce que vous avez de la nourriture pour moi ?$b$bJ\'ai l\'impression de ne jamais avoir le temps de quitter le magasin, même pas une minute.',0);
