INSERT IGNORE INTO `quest_request_items_locale` VALUES (13102,'frFR','J\'ai des gens affamés ici ! Nous avons besoin de ragoût.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13103,'frFR','Avez-vous vu un serviteur avec mon plateau de vin et de fromages ? J\'ai le ventre creux !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13107,'frFR','Je suis presque prêt, j\'ai seulement besoin de nourriture et que mes copains... euh... mes collègues mages arrivent.',0);
