INSERT IGNORE INTO `quest_request_items_locale` VALUES (13112,'frFR','Vous avez quelque chose pour moi ? Je sors si rarement de mon échoppe.',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13113,'frFR','Où est ma nourriture ? Mes invités seront bientôt là !',0);
INSERT IGNORE INTO `quest_request_items_locale` VALUES (13114,'frFR','Assurez-vous qu\'il n\'y ait pas de gnomes dans le ragoût cette fois-ci !',0);
